 const checkedAt=diagnostics?.checkedAt&&Number.isFinite(Date.parse(diagnostics.checkedAt))?date(diagnostics.checkedAt):'未知';
 const booleanStatus=(value:unknown,yes:string,no:string)=>value===true?yes:value===false?no:'未知';
 const limitations:Record<string,string>={checkout_disabled_until_production_qa:'建单与核验已实现；仍须完成生产验收后启用',adapter_not_implemented:'通道适配尚未接入',new_orders_stopped:'已停止新订单'};
 const version=typeof gateway?.version==='string'&&/^v?\d+(?:\.\d+){1,3}(?:[-+][a-zA-Z0-9.-]{1,24})?$/.test(gateway.version)?gateway.version:'未提供';
 return <section className="panel payment-channels-panel" aria-labelledby="payment-channels-title" aria-busy={state.status==='loading'}><div className="panel-heading"><div><h2 id="payment-channels-title">GSPAY+ 充值通道</h2></div><button type="button" className="secondary" disabled={state.status==='loading'} onClick={()=>setRevision(value=>value+1)}>{state.status==='error'?'重试通道状态':'刷新通道状态'}</button></div><div className="payment-channels-content">
  <div className="payment-channel-grid">{(Object.keys(paymentChannelLabels) as PaymentChannelId[]).filter(id=>id!=='vpay').map(id=><button key={id} type="button" className="payment-channel" disabled data-channel={id}><strong>{paymentChannelLabels[id]}</strong><span>{state.status==='ready'?'接线中 · 暂未开放':state.status==='loading'?'正在读取…':'状态未知'}</span></button>)}</div>
  <p className={'payment-channel-notice '+(state.status==='error'?'failed':'')} role={state.status==='error'?'alert':'status'}>{state.status==='error'?'暂时无法读取通道状态，请重试。':state.status==='loading'?'正在读取通道状态…':'暂未开放'}</p>
  {showDiagnostics&&<details className="payment-diagnostics"><summary>总部通道检查</summary><p>以下只显示脱敏布尔状态；不会显示厂家密钥、机器令牌或后台资料。</p>{gspay&&<><h3>GSPAY+ MYR 门户状态</h3><dl className="payment-diagnostics-grid"><div><dt>厂家建单格式</dt><dd>{booleanStatus(gspay.providerSchemaConfirmed,'已确认','待确认')}</dd></div><div><dt>会员建单</dt><dd>{booleanStatus(gspay.ordersEnabled,'已开放','已关闭')}</dd></div><div><dt>回调处理</dt><dd>{booleanStatus(gspay.callbacksEnabled,'已开放','已关闭')}</dd></div><div><dt>独立查单</dt><dd>{booleanStatus(gspay.queryEnabled,'已开放','已关闭')}</dd></div><div><dt>钱包结算</dt><dd>{booleanStatus(gspay.settlementEnabled,'已开放','已关闭')}</dd></div><div><dt>上线条件</dt><dd>{booleanStatus(gspay.liveReady,'已满足','未满足')}</dd></div></dl><ul className="payment-channel-limitations">{gspay.blockers.map(code=><li key={code}><b>GSPAY+ MYR</b><span>{code==='GSPAY_CREATE_SCHEMA_UNCONFIRMED'?'厂家建单成功响应与收银台字段尚待确认':code==='GSPAY_SETTLEMENT_DISABLED'?'结算保持关闭，等待厂家协议与生产验收':'存在未关闭的接线条件'}</span></li>)}</ul></>}{diagnostics?<><h3>现有网关检查</h3><dl className="payment-diagnostics-grid"><div><dt>检查时间（MYT）</dt><dd>{checkedAt}</dd></div><div><dt>网关连接</dt><dd>{booleanStatus(gateway?.reachable,'可连接','未连接')}</dd></div><div><dt>网关环境</dt><dd>{gateway?.mode==='uat'?'测试环境':gateway?.mode==='production'?'正式环境':'未知'}</dd></div><div><dt>配置资料</dt><dd>{booleanStatus(gateway?.configured,'已提供','未提供')}</dd></div><div><dt>配置校验</dt><dd>{booleanStatus(gateway?.configurationReady,'通过','未通过')}</dd></div><div><dt>网关上线条件</dt><dd>{booleanStatus(gateway?.liveReady,'服务报告通过','未满足')}</dd></div><div><dt>网关版本</dt><dd>{version}</dd></div><div><dt>检查结果</dt><dd>{gateway&&Object.hasOwn(gateway,'errorCode')?(gateway.errorCode?'状态未能完整确认':'已返回检查结果'):'未知'}</dd></div></dl><ul className="payment-channel-limitations">{(Object.keys(paymentChannelLabels) as PaymentChannelId[]).map(id=><li key={id}><b>{paymentChannelLabels[id]}</b><span>{limitations[diagnostics.limitations?.[id]]||'状态未确认'}</span></li>)}</ul></>:<p className="payment-diagnostics-unknown">{state.status==='loading'?'正在读取检查结果…':'网关检查结果未知，请重试通道状态。'}</p>}</details>}
 </div></section>;
