function Empty({text}:{text:string}){return <div className="empty"><ClipboardList size={30}/><p>{text}</p></div>}
function Status({value}:{value:string}){return <span className={'tag '+(value==='已完成'?'done':value==='处理中'?'progress':'')}>{value}</span>}
function SearchBox({value,set}:{value:string;set:(v:string)=>void}){return <label className="search"><Search size={17}/><input aria-label="搜索" placeholder="搜索内容…" value={value} onChange={e=>set(e.target.value)}/></label>}
